// denseMatrixMul returns m·x.
func denseMatrixMul(m [][]fr.Element, x []fr.Element) []fr.Element {
	res := make([]fr.Element, len(m))
	for i := range m {
		var tmp fr.Element
		for j := range m[i] {
			tmp.Mul(&m[i][j], &x[j])
			res[i].Add(&res[i], &tmp)
		}
	}
	return res
}

// TestMatricesMatchInPlace checks that the dense matrices act on a random
// state as the in-place multiplications of the permutation.
func TestMatricesMatchInPlace(t *testing.T) {
	for _, tc := range []struct {
		width, nbFullRounds, nbPartialRounds int
	}{
		{16, 8, 32},
		{24, 8, 32},
	} {
		h := NewPermutation(tc.width, tc.nbFullRounds, tc.nbPartialRounds)

		for name, step := range map[string]struct {
			dense   [][]fr.Element
			inPlace func([]fr.Element)
		}{
			"external": {h.params.ExternalMatrix(), h.matMulExternalInPlace},
			"internal": {h.params.InternalMatrix(), h.matMulInternalInPlace},
		} {
			x := make([]fr.Element, tc.width)
			for i := range x {
				x[i].MustSetRandom()
			}
			want := denseMatrixMul(step.dense, x)
			step.inPlace(x)
			for i := range x {
				if !x[i].Equal(&want[i]) {
					t.Fatalf("width %d, %s matrix: dense and in-place multiplications differ at index %d", tc.width, name, i)
				}
			}
		}
	}
}

// testElements returns n deterministic elements, which differ with seed.
func testElements(n int, seed uint64) []fr.Element {
	e := make([]fr.Element, n)
	for i := range e {
		e[i].SetUint64(seed*1_000_003 + uint64(i)*2_654_435_761 + 1)
	}
	return e
}

func marshalElements(e []fr.Element) []byte {
	var b []byte
	for i := range e {
		x := e[i].Bytes()
		b = append(b, x[:]...)
	}
	return b
}

// lengths are numbers of elements around block boundaries.
var lengths = []int{0, 1, blockLen - 1, blockLen, blockLen + 1, 2*blockLen + 3, 37}

// TestHasherSplitWrites checks that the digest does not depend on how the
// elements are split among the writes.
func TestHasherSplitWrites(t *testing.T) {
	for _, n := range lengths {
		elems := testElements(n, 1)
		whole := NewHasher()
		whole.WriteElements(elems...)
		want := whole.SumElement()

		h := NewHasher()
		for _, e := range elems {
			h.WriteElement(e)
		}
		require.Equal(t, want, h.SumElement(), "n=%d, one by one", n)

		for split := 0; split <= n; split++ {
			h.Reset()
			h.WriteElements(elems[:split]...)
			h.WriteElements(elems[split:]...)
			require.Equal(t, want, h.SumElement(), "n=%d, split at %d", n, split)
		}

		h.Reset()
		rest := elems
		for i := 0; len(rest) != 0; i++ {
			switch i % 3 {
			case 0:
				h.WriteElement(rest[0])
				rest = rest[1:]
			case 1:
				k := min(len(rest), blockLen+1)
				h.WriteElements(rest[:k]...)
				rest = rest[k:]
			default:
				k := min(len(rest), 2)
				h.WriteElements(rest[:k]...)
				rest = rest[k:]
			}
		}
		require.Equal(t, want, h.SumElement(), "n=%d, mixed", n)
	}
}

// TestHasherSumElement checks that SumElement does not change the state, and
// that it pads an incomplete block as PadBlock.
func TestHasherSumElement(t *testing.T) {
	elems := testElements(3*blockLen+1, 2)
	h := NewHasher()
	for i := range elems {
		h.WriteElement(elems[i])
		sum := h.SumElement()
		require.Equal(t, sum, h.SumElement())

		padded := NewHasher()
		padded.WriteElements(elems[:i+1]...)
		padded.PadBlock()
		require.Equal(t, sum, padded.SumElement(), "after %d elements", i+1)
	}
	whole := NewHasher()
	whole.WriteElements(elems...)
	require.Equal(t, whole.SumElement(), h.SumElement())
}

// TestHasherPadBlock checks that PadBlock pads the incomplete block with zeros
// on the left, and does nothing if there is no incomplete block.
func TestHasherPadBlock(t *testing.T) {
	tail := testElements(blockLen+2, 3)
	for k := 0; k <= blockLen; k++ {
		head := testElements(k, 4)

		h := NewHasher()
		h.WriteElements(head...)
		h.PadBlock()
		h.WriteElements(tail...)

		want := NewHasher()
		want.WriteElements(make([]fr.Element, (blockLen-k)%blockLen)...)
		want.WriteElements(head...)
		want.WriteElements(tail...)
		require.Equal(t, want.SumElement(), h.SumElement(), "k=%d", k)
	}
}

func TestHasherReset(t *testing.T) {
	elems := testElements(2*blockLen+1, 5)
	fresh := NewHasher()
	fresh.WriteElements(elems...)

	h := NewHasher()
	h.WriteElements(testElements(blockLen+1, 6)...)
	h.Reset()
	h.WriteElements(elems...)
	require.Equal(t, fresh.SumElement(), h.SumElement())

	h.Reset()
	require.Equal(t, NewHasher().SumElement(), h.SumElement())
}

// TestMerkleDamgard checks the hasher of bytes against the digests of the field
// hasher, and against the byte Merkle-Damgard hasher over [Permutation.Compress].
func TestMerkleDamgard(t *testing.T) {
	p := NewDefaultPermutation()
	newRef := func() gnarkHash.StateStorer {
		return gnarkHash.NewMerkleDamgardHasher(p, make([]byte, p.BlockSize()))
	}

	for _, n := range lengths {
		elems := testElements(n, 7)
		data := marshalElements(elems)

		field := NewHasher()
		field.WriteElements(elems...)
		fieldDigest := marshalElements(func() []fr.Element { d := field.SumElement(); return d[:] }())

		h := NewMerkleDamgardHasher()
		ref := newRef()
		for _, w := range []gnarkHash.StateStorer{h, ref} {
			written, err := w.Write(data)
			require.NoError(t, err)
			require.Equal(t, len(data), written)
		}
		require.Equal(t, ref.Sum(nil), h.Sum(nil), "n=%d", n)
		require.Equal(t, fieldDigest, h.Sum(nil), "n=%d", n)
		require.Equal(t, ref.State(), h.State(), "n=%d", n)

		// a write of fewer bytes than an element
		for k := 1; k < fr.Bytes; k++ {
			short := bytes.Repeat([]byte{1}, k)
			for _, w := range []gnarkHash.StateStorer{h, ref} {
				written, err := w.Write(short)
				require.NoError(t, err)
				require.Equal(t, k, written)
			}
			require.Equal(t, ref.Sum(nil), h.Sum(nil), "n=%d, %d more bytes", n, k)
		}

		// a hasher restored from the state continues as the original
		restored := NewMerkleDamgardHasher()
		require.NoError(t, restored.SetState(h.State()))
		more := marshalElements(testElements(blockLen+1, 8))
		for _, w := range []gnarkHash.StateStorer{h, restored, ref} {
			_, err := w.Write(more)
			require.NoError(t, err)
		}
		require.Equal(t, ref.Sum(nil), h.Sum(nil), "n=%d, after more", n)
		require.Equal(t, ref.Sum(nil), restored.Sum(nil), "n=%d, restored", n)

		h.Reset()
		ref.Reset()
		require.Equal(t, ref.Sum(nil), h.Sum(nil), "n=%d, reset", n)
	}
}

// writeElements writes the elements with WriteElement, as a generic consumer of
// any field hasher does.
func writeElements[H gnarkHash.FieldHasher[fr.Element, [blockLen]fr.Element]](h H, e []fr.Element) {
	for i := range e {
		h.WriteElement(e[i])
	}
}

// TestHasherAllocs checks that hashing elements does not allocate, including
// WriteElement called by a generic function, and SumElement with an incomplete
// block.
func TestHasherAllocs(t *testing.T) {
	h := NewHasher()
	elems := testElements(3*blockLen+1, 9)
	var fh gnarkHash.FieldHasher[fr.Element, [blockLen]fr.Element] = h

	require.Zero(t, testing.AllocsPerRun(100, func() { writeElements(h, elems) }), "generic WriteElement on *Hasher")
	require.Zero(t, testing.AllocsPerRun(100, func() { writeElements(fh, elems) }), "generic WriteElement on the interface")
	require.Zero(t, testing.AllocsPerRun(100, func() { h.WriteElements(elems...) }), "WriteElements")
	require.Zero(t, testing.AllocsPerRun(100, func() { fh.WriteElements(elems...) }), "WriteElements on the interface")

	// a state with one element pending, and one without
	h.Reset()
	h.WriteElement(elems[0])
	require.Zero(t, testing.AllocsPerRun(100, func() { _ = h.SumElement() }), "SumElement of an incomplete block")
	require.Zero(t, testing.AllocsPerRun(100, func() { _ = fh.SumElement() }), "SumElement of an incomplete block on the interface")
	h.PadBlock()
	require.Zero(t, testing.AllocsPerRun(100, func() { _ = h.SumElement() }), "SumElement of a complete block")
	require.Zero(t, testing.AllocsPerRun(100, func() {
		h.WriteElement(elems[0])
		h.PadBlock()
	}), "PadBlock of an incomplete block")
}

